<?php require __DIR__ . '/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow"><?= h(t('employees.hr')) ?></span><h1><?= h($title) ?></h1><p class="muted"><?= $employee ? h($employee['first_name'] . ' ' . $employee['last_name'] . ' · ' . $employee['employee_number']) : h(t('hr.history_intro')) ?></p></div>
<?php if ($canNew): ?><a class="button primary" href="/<?= h($kind) ?>/new<?= $employee ? '?employee_id=' . h($employee['id']) : '' ?>"><?= h(t('hr.new_' . $kind)) ?></a><?php endif; ?></div>
<section class="card table-card"><div class="table-toolbar"><h2><?= h(t('hr.history')) ?> <span class="count"><?= h($result['total']) ?></span></h2><?php if ($employee): ?><a class="text-link" href="/<?= h($kind) ?>"><?= h(t('hr.all_records')) ?></a><?php endif; ?></div>
<div class="table-scroll"><table><thead><tr><th><?= h(t('employees.person')) ?></th><th><?= h(t($kind === 'contracts' ? 'hr.reference_type' : 'hr.department_position')) ?></th><th><?= h(t('hr.starts_on')) ?></th><th><?= h(t('hr.effective_end')) ?></th><th><?= h(t('employees.state')) ?></th><th><?= h(t('common.actions')) ?></th></tr></thead><tbody>
<?php foreach ($result['rows'] as $item): ?><tr><td><strong><?= h($item['first_name'] . ' ' . $item['last_name']) ?></strong><br><small class="mono"><?= h($item['employee_number']) ?></small></td><td><?php if ($kind === 'contracts'): ?><?= h($item['reference']) ?><br><small><?= h(t('hr.type.' . $item['contract_type'])) ?></small><?php else: ?><?= h($item['department_label']) ?><br><small><?= h($item['position_label']) ?></small><?php endif; ?></td><td><?= h($item['starts_on']) ?></td><td><?= h($item['effective_ends_on'] ?? t('hr.open_ended')) ?></td><td><span class="badge <?= \App\HR\PeriodValidation::status($item) === 'hr.status.ended' ? 'archived' : '' ?>"><?= h(t(\App\HR\PeriodValidation::status($item))) ?></span></td><td><a class="text-link" href="/<?= h($kind) ?>/<?= h($item['id']) ?>"><?= h(t('hr.view_record')) ?> →</a></td></tr><?php endforeach; ?>
<?php if ($result['rows'] === []): ?><tr><td colspan="6"><div class="empty"><h3><?= h(t('hr.no_records')) ?></h3><p class="muted"><?= h(t('hr.no_records_help')) ?></p></div></td></tr><?php endif; ?>
</tbody></table></div><div class="pagination"><span class="muted"><?= h(t('employees.pagination', ['page' => $result['page'], 'pages' => max(1, (int) ceil($result['total'] / 20))])) ?></span><div>
<?php if ($result['page'] > 1): ?><a class="button secondary" href="/<?= h($kind) ?>?<?= h(http_build_query(array_filter(['employee_id' => $employee['id'] ?? null, 'page' => $result['page'] - 1]))) ?>"><?= h(t('employees.previous')) ?></a><?php endif; ?>
<?php if ($result['page'] * 20 < $result['total']): ?><a class="button secondary" href="/<?= h($kind) ?>?<?= h(http_build_query(array_filter(['employee_id' => $employee['id'] ?? null, 'page' => $result['page'] + 1]))) ?>"><?= h(t('employees.next')) ?></a><?php endif; ?>
</div></div></section>
<?php require __DIR__ . '/footer.php'; ?>
